    for (let i = 0; i < N; i++) {
      let u = z[i];
      if (!isFinite(u)) u = 0.5;
      u = clamp01(u);
      x[i] = PLB[i] + (PUB[i] - PLB[i]) * u;
    }
    return x;
  }

