  function evaluate(src, tag) {
    if (left() <= 0 || timeUp()) {
      return {
        x: makeX(src), fit: -1e100, d: 0, outcome: "error",
        time: 0, energy: 0, tag: tag
      };
    }

    const xx = makeX(src);
    let r = null;
    try {
      r = lab.trial(xx);
    } catch (e) {
      r = null;
    }
    used++;

    let d = 0;
    let tm = 0;
    let outcome = "error";
    let energy = 0;

    if (r) {
      d = Number(r.distance);
      if (!isFinite(d) || d < 0) d = 0;
      tm = Number(r.time);
      if (!isFinite(tm)) tm = 0;
      outcome = String(r.outcome || "error");
      energy = Number(r.energy);
      if (!isFinite(energy)) energy = 0;
    }

