    if (outcome === "finished") {
      fit = d * 1.85 + 0.02 * tm + 0.2;
    } else if (outcome === "fell") {
      fit = d + 0.02 * tm;
    } else if (outcome === "invalid" || outcome === "error") {
      fit = -100000 + d;
    } else {
      fit = d + 0.02 * tm;
    }

    const rec = {
      x: xx, fit: fit, d: d, outcome: outcome,
      time: tm, energy: energy, tag: tag
    };

    allRecs.push(rec);

    if ((outcome === "finished" || outcome === "fell") && (!bestValid || rec.fit > bestValid.fit)) {
      bestValid = rec;
    }
    if (outcome === "finished" && (!bestStable || rec.fit > bestStable.fit)) {
      bestStable = rec;
    }
    if (!bestOverall || rec.fit > bestOverall.fit) {
      bestOverall = rec;
    }

    return rec;
  }

  const seeds = [];

  function addSeed(fn) {
    const a = PDEF.slice();
    if (fn) fn(a);
    seeds.push(makeX(a));
  }

  addSeed(null);

  addSeed(function(a) {
    a[0] = 2.0; a[1] = 0.50; a[4] = 0.68; a[8] = 0.20;
    a[14] = -0.12; a[15] = 4.0; a[16] = 1.0; a[17] = 0.8;
    a[18] = 1.8; a[10] = 6.0; a[12] = 8.0; a[30] = 0.70;
  });

