    a[0] = 2.4; a[1] = 0.45; a[4] = 0.82; a[8] = 0.19;
    a[14] = -0.18; a[15] = 5.0; a[16] = 1.2; a[17] = 1.2;
    a[18] = 2.5; a[10] = 7.0; a[12] = 9.0; a[30] = 0.60;
  });

  addSeed(function(a) {
    a[0] = 1.35; a[1] = 0.65; a[4] = 0.35; a[8] = 0.12;
    a[14] = -0.05; a[15] = 2.0; a[16] = 0.4; a[17] = 0.3;
    a[18] = 0.7; a[6] = 0.852; a[30] = 1.0;
