  addSeed(function(a) {
    a[0] = 2.2; a[1] = 0.42; a[2] = 0.0; a[4] = 0.42;
    a[8] = 0.22; a[14] = -0.12; a[15] = 5.0; a[16] = 1.0;
    a[17] = 0.7; a[18] = 1.5; a[19] = 0.7; a[30] = 0.60;
    a[10] = 6.0; a[12] = 8.0;
