    a[17] = 1.0; a[18] = 2.0; a[19] = 0.6; a[30] = 0.50;
    a[10] = 7.0; a[12] = 9.0;
  });

  addSeed(function(a) {
    a[0] = 1.7; a[1] = 0.55; a[2] = 0.02; a[4] = 0.25;
    a[8] = 0.12; a[14] = -0.05; a[15] = 3.0; a[16] = 0.7;
    a[17] = 0.5; a[18] = 0.8; a[19] = 0.8; a[30] = 0.80;
