    a[15] = -2.5; a[16] = -0.5; a[17] = -0.4;
  });

  addSeed(function(a) {
    a[15] = -2.5; a[16] = -0.5; a[17] = -0.4;
    a[20] = 0.6; a[21] = -0.25;
  });

  addSeed(function(a) {
    a[0] = 1.32; a[1] = 0.51; a[2] = 0.47; a[3] = 0.17;
    a[4] = 0.58; a[5] = 0.06; a[6] = 0.84; a[8] = 0.16;
    a[10] = 3.2; a[11] = 1.6; a[12] = 4.7; a[13] = 2.3;
    a[14] = 0.15; a[15] = 1.3; a[16] = 1.6; a[17] = -0.6;
    a[18] = 2.3; a[19] = 0.35; a[20] = 2.8; a[21] = 0.23;
  });

  addSeed(function(a) { a[3] = 0.25; });
  addSeed(function(a) { a[3] = 0.45; });
  addSeed(function(a) { a[3] = 0.70; });
  addSeed(function(a) { a[3] = 0.90; });

  addSeed(function(a) {
    a[0] = 3.0; a[1] = 0.65; a[4] = 0.25; a[8] = 0.12;
    a[18] = 0.8; a[19] = 0.9; a[14] = -0.04;
  });

  addSeed(function(a) {
    a[0] = 1.2; a[1] = 0.62; a[4] = 0.45; a[6] = 0.80;
    a[7] = 0.08; a[14] = -0.05; a[15] = 3.0;
  });

  addSeed(function(a) {
    a[2] = 0.0; a[0] = 2.6; a[1] = 0.40; a[4] = 0.55;
    a[8] = 0.18; a[14] = -0.20; a[15] = 5.5;
    a[16] = 1.2; a[17] = 1.0; a[18] = 2.4; a[19] = 0.6;
  });

  addSeed(function(a) { a[31] = 2.2; });
  addSeed(function(a) { a[2] = 0.0; a[31] = 2.2; });

  for (let si = 0; si < seeds.length; si++) {
    if (left() <= 4 || timeUp()) break;
    evaluate(seeds[si], "seed" + si);
  }

  let broadCenter = bestValid ? bestValid.x : PDEF;
  for (let k = 0; k < 45; k++) {
    if (left() <= 5 || timeUp()) break;

    let baseArr;
    if (k % 3 === 0) baseArr = PDEF;
    else if (k % 3 === 1) baseArr = broadCenter;
    else baseArr = bestOverall ? bestOverall.x : PDEF;

    const z = normX(baseArr);
    for (let i = 0; i < N; i++) {
      if (Math.random() < 0.06) {
        z[i] = Math.random();
      } else {
        let sg = i === 2 ? 0.16 : (i < 10 ? 0.22 : 0.25);
        z[i] = clamp01(z[i] + gauss() * sg);
      }
    }
    evaluate(denorm(z), "broad" + k);
  }

  function bestMatching(fn) {
    let b = null;
    for (let i = 0; i < allRecs.length; i++) {
      const r = allRecs[i];
      if ((r.outcome === "finished" || r.outcome === "fell") && fn(r)) {
        if (!b || r.fit > b.fit) b = r;
      }
    }
    return b;
  }

  const walkCenter = bestMatching(function(r) {
    const s = r.x[2];
    return s > 0.22 && s < 0.78;
  });

  const hopCenter = bestMatching(function(r) {
    const s = r.x[2];
    return s <= 0.22 || s >= 0.78;
  });

  function runCEM(centerRec, budget, sig, mode) {
    if (left() <= 2 || budget < 4 || timeUp()) return null;
    if (!centerRec || !centerRec.x) centerRec = { x: PDEF.slice() };

    let cX = makeX(centerRec.x);
    if (mode === "walk") cX[2] = 0.5;
    if (mode === "hop") cX[2] = 0.0;

    let mean = normX(cX);
    const std = new Array(N);

    for (let i = 0; i < N; i++) std[i] = sig;

    if (mode !== "local") {
      std[0] = 0.11;
      std[1] = 0.07;
      std[2] = mode === "walk" ? 0.035 : 0.012;
      std[3] = 0.08;
      std[4] = 0.16;
      std[5] = 0.10;
      std[6] = 0.035;
      std[7] = 0.06;
      std[8] = 0.08;
      std[9] = 0.08;
      std[10] = 0.16;
      std[11] = 0.15;
      std[12] = 0.16;
      std[13] = 0.15;
      std[14] = 0.08;
      std[15] = 0.18;
      std[16] = 0.18;
      std[17] = 0.18;
      std[18] = 0.16;
      std[19] = 0.15;
      std[20] = 0.16;
      std[21] = 0.16;
      std[22] = 0.14;
      std[23] = 0.14;
      std[24] = 0.12;
      std[25] = 0.12;
      std[26] = 0.12;
      std[27] = 0.12;
      std[28] = 0.15;
      std[29] = 0.12;
      std[30] = 0.10;
      std[31] = 0.15;
      std[32] = 0.12;
      std[33] = 0.12;
      std[34] = 0.10;
      std[35] = 0.10;
    }

    const startUsed = used;
    const init = evaluate(cX, mode + "Init");
    let localBest = init;
    let gen = 0;
    let noImp = 0;

    while ((used - startUsed) < budget && left() > 3 && !timeUp()) {
      const remain = budget - (used - startUsed);
      let popSize = Math.min(mode === "local" ? 14 : 24, remain, left());
      if (popSize < 4) break;

      const pop = [];

      for (let k = 0; k < popSize; k++) {
        if (left() <= 0 || timeUp()) break;

        let z;
        if (k === 0) {
          z = mean.slice();
        } else if (k === 1 && localBest) {
          z = normX(localBest.x);
        } else if (k === 2 && bestOverall) {
          z = normX(bestOverall.x);
        } else {
          z = new Array(N);
          const globalRand = Math.random() < (gen < 2 ? 0.10 : 0.025);
          for (let i = 0; i < N; i++) {
            if (globalRand && i !== 2) {
              z[i] = Math.random();
            } else {
              z[i] = clamp01(mean[i] + std[i] * gauss());
            }
          }
        }

        if (mode === "walk") {
          if (z[2] < 0.15) z[2] = 0.15;
          if (z[2] > 0.85) z[2] = 0.85;
        }
        if (mode === "hop") {
          if (z[2] < 0) z[2] = 0;
          if (z[2] > 0.15) z[2] = 0.15;
        }

        const rec = evaluate(denorm(z), mode + "_" + gen + "_" + k);
        pop.push({ z: z, rec: rec });
      }

      if (pop.length < 4) break;

      pop.sort(function(a, b) {
        return b.rec.fit - a.rec.fit;
      });

      if (pop[0].rec.fit > localBest.fit) {
        localBest = pop[0].rec;
        noImp = 0;
      } else {
        noImp++;
      }

      let K = Math.max(3, Math.floor(pop.length * 0.25));
      if (K > pop.length) K = pop.length;

      const m = new Array(N);
      const varz = new Array(N);

      for (let i = 0; i < N; i++) {
        let sumW = 0;
        let mi = 0;
        for (let j = 0; j < K; j++) {
          const w = Math.exp(-0.35 * j);
          mi += w * pop[j].z[i];
          sumW += w;
        }
        mi /= sumW;

        let vv = 0;
        for (let j = 0; j < K; j++) {
          const w = Math.exp(-0.35 * j);
          const di = pop[j].z[i] - mi;
          vv += w * di * di;
        }
        vv /= sumW;

        m[i] = mi;
        varz[i] = vv;
      }

      for (let i = 0; i < N; i++) {
        mean[i] = 0.35 * mean[i] + 0.65 * m[i];

        let nstd = 0.50 * std[i] + 0.50 * Math.sqrt(varz[i]);
        const floor = mode === "local" ? 0.006 : 0.012;
        if (nstd < floor) nstd = floor;
        if (mode === "local" && nstd > 0.10) nstd = 0.10;
        if (nstd > 0.55) nstd = 0.55;
        std[i] = nstd;
      }

      if (mode === "walk") {
        if (mean[2] < 0.18) mean[2] = 0.18;
        if (mean[2] > 0.82) mean[2] = 0.82;
        if (std[2] > 0.06) std[2] = 0.06;
      }
      if (mode === "hop") {
        if (mean[2] < 0) mean[2] = 0;
        if (mean[2] > 0.15) mean[2] = 0.15;
        if (std[2] > 0.03) std[2] = 0.03;
      }

      if (noImp > 6 && gen > 2 && bestOverall) {
        const bz = normX(bestOverall.x);
        for (let i = 0; i < N; i++) {
          mean[i] = 0.70 * mean[i] + 0.30 * bz[i];
          if (std[i] < 0.05) std[i] = 0.05;
        }
        noImp = 0;
      }

      gen++;
    }

    return localBest;
  }

  let remaining = left();
  if (remaining > 10 && !timeUp()) {
    let walkBudget = Math.min(470, Math.floor(remaining * 0.55));
    if (walkBudget >= 6) runCEM(walkCenter, walkBudget, 0.18, "walk");
  }

  remaining = left();
  if (remaining > 10 && !timeUp()) {
    let hopBudget = Math.min(300, Math.floor(remaining * 0.55));
    if (hopBudget >= 6) runCEM(hopCenter, hopBudget, 0.20, "hop");
  }

  remaining = left();
  if (remaining > 5 && !timeUp()) {
    let localBudget = Math.min(260, remaining - 5);
    if (localBudget >= 4) runCEM(bestOverall, localBudget, 0.07, "local");
  }

  remaining = left();
  if (remaining > 8 && !timeUp()) {
    let extra = Math.min(remaining - 5, 180);
    if (extra >= 4) runCEM(bestOverall, extra, 0.04, "local");
  }

  let chosen = bestOverall;
  if (!chosen || chosen.outcome === "invalid" || chosen.outcome === "error") {
    chosen = bestValid || bestStable || { x: makeX(PDEF) };
  }

  if (bestStable && chosen !== bestStable && chosen.outcome !== "finished") {
    if (bestStable.d >= chosen.d * 0.60 || bestStable.fit >= chosen.fit - 0.3) {
      chosen = bestStable;
    }
  }

  if (!chosen || !chosen.x) return PDEF.slice();
  return makeX(chosen.x);
}

const DEF = [
  1.80, 0.58, 0.50, 0.00, 0.60, 0.845, 0.040, 0.200, 0.00,
  8.0, 0.80, 10.0, 1.00,
  -0.08, 6.0, 1.0, 0.8, 1.60, 0.70,
  0.10, 0.40,
  1.12, 8.0, 0.50,
  0.25, 0.12, 4.0, 0.06,
  0.20, 5.0,
  0.00, 0.00,
  1.0, 0.02, 0.0, 0.0, 0.40
];

const LB = [
  0.30, 0.20, 0.00, 0.00, 0.00, 0.55, 0.00, 0.00, -0.60,
  0.50, 0.00, 0.50, 0.00,
  -0.80, -10.0, -6.0, -4.0, -0.50, 0.0,
  -0.80, -2.0,
  0.65, 0.0, 0.0,
  0.0, -0.80, 0.0, 0.0,
  0.01, 0.0,
  -0.80, -0.80,
  0.0, 0.0, -0.40, 0.0, 0.0
];

const UB = [
  4.00, 0.90, 1.00, 1.00, 1.20, 0.868, 0.40, 0.70, 0.60,
  40.0, 8.0, 45.0, 8.0,
  0.60, 30.0, 6.0, 8.0, 5.00, 1.0,
  0.80, 2.0,
  1.35, 50.0, 6.0,
  1.20, 1.00, 40.0, 0.45,
  1.50, 50.0,
  0.80, 0.80,
  1.5, 0.15, 0.40, 6.283185, 3.0
];

function policy(obs, params, mem) {
  const PI = Math.PI;
  const TWOPI = 2 * PI;
  const L1 = 0.51;
  const L2 = 0.36;
  const D = 0.345;

  let p = params;
  if (!p || typeof p.length !== "number" || p.length < DEF.length) p = DEF;

  function get(i) {
    let v = p[i];
    if (typeof v !== "number" || !isFinite(v)) v = DEF[i];
    if (v < LB[i]) v = LB[i];
    if (v > UB[i]) v = UB[i];
    return v;
  }

  const freq = get(0);
  const duty = get(1);
  const legOff = get(2);
  const phase0 = get(3);
  const stride = get(4);
  const legLen = get(5);
  const crouch = get(6);
  const lift = get(7);
  const hipBias = get(8);

  const hKp = get(9);
  const hKd = get(10);
  const kKp = get(11);
  const kKd = get(12);

  const leanTarget = get(13);
  const balTheta = get(14);
  const balSpin = get(15);
  const balVel = get(16);
  const targetVx = get(17);
  const contactW = get(18);

  const stepVelGain = get(19);
  const stepAngleGain = get(20);

  const heightTarget = get(21);
  const heightGain = get(22);
  const heightVelGain = get(23);

  const obstacleLift = get(24);
  const obstacleHip = get(25);
  const clearanceGain = get(26);
  const clearanceHeight = get(27);

  const startRamp = get(28);
  const recoverGain = get(29);

  const directHip = get(30);
  const directKnee = get(31);
  const hipComp = get(32);
  const stancePush = get(33);
  const kneeStanceBias = get(34);
  const phaseSin = get(35);
  const contactStraight = get(36);

  const theta = +obs[0] || 0;
  const spin = +obs[1] || 0;
  const vx = +obs[2] || 0;
  const vy = +obs[3] || 0;
  const height = +obs[4] || 0;
  const t = +obs[19] || 0;

  const hipA = +obs[5] || 0;
  const hipAs = +obs[6] || 0;
  const kneeA = +obs[7] || 0;
  const kneeAs = +obs[8] || 0;
  const footA = +obs[9] || 0;

  const hipB = +obs[10] || 0;
  const hipBs = +obs[11] || 0;
  const kneeB = +obs[12] || 0;
  const kneeBs = +obs[13] || 0;
  const footB = +obs[14] || 0;

  const a1 = +obs[15] || 0;
  const a2 = +obs[16] || 0;
  const a3 = +obs[17] || 0;
  const a4 = +obs[18] || 0;

  if (!mem || typeof mem !== "object") mem = {};

  let rawObs = Math.max(0, a1 * 0.8, a2, a3 * 0.6, a4 * 0.35);
  if (!isFinite(rawObs)) rawObs = 0;
  if (rawObs > 0.8) rawObs = 0.8;
  if (typeof mem.oh !== "number" || !isFinite(mem.oh)) mem.oh = rawObs;
  else mem.oh += 0.22 * (rawObs - mem.oh);
  let oh = mem.oh;
  if (oh < 0) oh = 0;
  if (oh > 0.8) oh = 0.8;

  let ramp = 1;
  if (startRamp > 0.001 && t < startRamp) {
    let u = t / startRamp;
    if (u < 0) u = 0;
    if (u > 1) u = 1;
    ramp = u * u * (3 - 2 * u);
  }

  function terrainAt(x) {
    if (!isFinite(x)) return 0;
    if (x <= 0) return 0;
    if (x < 0.5) return a1 * (x / 0.5);
    if (x < 1.0) return a1 + (a2 - a1) * ((x - 0.5) / 0.5);
    if (x < 2.0) return a2 + (a3 - a2) * (x - 1.0);
    if (x < 4.0) return a3 + (a4 - a3) * ((x - 2.0) / 2.0);
    return a4 + ((a4 - a3) / 2.0) * (x - 4.0);
  }

  function clampAngle(h, k) {
    if (h < -0.889) h = -0.889;
    if (h > 1.199) h = 1.199;
    if (k < -1.69) k = -1.69;
    if (k > -0.052) k = -0.052;
    return [h, k];
  }

  function solveIK(x, yd, extraHip) {
    if (!isFinite(x)) x = 0;
    if (!isFinite(yd)) yd = legLen;
    if (yd < 0.10) yd = 0.10;

    let r = Math.sqrt(x * x + yd * yd);
    const rmin = Math.abs(L1 - L2) + 0.020;
    const rmax = L1 + L2 - 0.004;

    if (r < 1e-9) {
      x = 0;
      yd = 0.4;
      r = 0.4;
    }
    if (r < rmin) {
      const sc = rmin / r;
      x *= sc;
      yd *= sc;
      r = rmin;
    } else if (r > rmax) {
      const sc = rmax / r;
      x *= sc;
      yd *= sc;
      r = rmax;
    }

    let cosk = (r * r - L1 * L1 - L2 * L2) / (2 * L1 * L2);
    if (cosk < -1) cosk = -1;
    if (cosk > 1) cosk = 1;

    let k = -Math.acos(cosk);
    const phi = Math.atan2(x, yd);
    const beta = Math.atan2(L2 * Math.sin(k), L1 + L2 * Math.cos(k));
    let h = phi - beta - theta * hipComp + hipBias + extraHip;

    const ck = clampAngle(h, k);
    return [ck[0], ck[1]];
  }

  function footPos(hip, knee) {
    const a1l = -PI * 0.5 + theta + hip;
    const a2l = a1l + knee;
    const hx = D * Math.sin(theta);
    const hy = height - D * Math.cos(theta);
    return [
      hx + L1 * Math.cos(a1l) + L2 * Math.cos(a2l),
      hy + L1 * Math.sin(a1l) + L2 * Math.sin(a2l)
    ];
  }

  function makeLeg(q, hipNow, kneeNow, footNow) {
    let stance = q < duty;
    let swing = 0;
    let x = 0;
    let yd = legLen;

    if (stance) {
      let s = q / duty;
      if (s < 0) s = 0;
      if (s > 1) s = 1;

      x = stride * (0.5 - s) * ramp;
      yd = legLen - crouch * Math.sin(PI * s) * ramp;
      yd += stancePush * Math.max(0, s - 0.55) * ramp;
    } else {
      swing = 1;
      let s = (q - duty) / (1 - duty);
      if (s < 0) s = 0;
      if (s > 1) s = 1;

      const u = s * s * (3 - 2 * s);

      x = stride * (-0.5 + u) * ramp;
      x += stepVelGain * (vx - targetVx) * ramp;
      x += stepAngleGain * (theta - leanTarget) * ramp;
      x += obstacleHip * oh * ramp;

      yd = legLen - lift * Math.sin(PI * s) * ramp - obstacleLift * oh * ramp;
    }

    let extraHip = directHip * Math.sin(TWOPI * q + phaseSin) * ramp;
    const sol = solveIK(x, yd, extraHip);
    let h = sol[0];
    let k = sol[1];

    if (stance) {
      k += kneeStanceBias * ramp;
    }

    if (swing && footNow < 0.5 && ramp > 0.04) {
      const fp = footPos(hipNow, kneeNow);
      const fx = fp[0];
      const fy = fp[1];
      const gy = terrainAt(fx);
      let desired = clearanceHeight + 0.55 * oh + 0.03;
      const gy2 = terrainAt(fx + 0.22);
      if (gy2 > gy) desired += 0.55 * (gy2 - gy);
      const clear = fy - gy;
      if (clear < desired) {
        k -= clearanceGain * (desired - clear);
      }
    }

    k += directKnee * Math.sin(TWOPI * q + phaseSin) * ramp;

    const ck = clampAngle(h, k);
    return [ck[0], ck[1], swing];
  }

  let base = phase0 + freq * t;
  base -= Math.floor(base);
  let qA = base;
  let qB = base + legOff;
  qB -= Math.floor(qB);

  const tgtA = makeLeg(qA, hipA, kneeA, footA);
  const tgtB = makeLeg(qB, hipB, kneeB, footB);

  let tauHA = hKp * (tgtA[0] - hipA) - hKd * hipAs;
  let tauHB = hKp * (tgtB[0] - hipB) - hKd * hipBs;

  let tauKA = kKp * (tgtA[1] - kneeA) - kKd * kneeAs;
  let tauKB = kKp * (tgtB[1] - kneeB) - kKd * kneeBs;

  const thetaErr = theta - leanTarget;
  const common = balTheta * thetaErr + balSpin * spin + balVel * (targetVx - vx);

  const wA = (1 - contactW) + contactW * footA;
  const wB = (1 - contactW) + contactW * footB;

  tauHA += common * wA;
  tauHB += common * wB;

  let heightErr = heightTarget - height;
  if (heightErr > 1.0) heightErr = 1.0;
  if (heightErr < -1.0) heightErr = -1.0;
  let heightExtra = heightGain * heightErr - heightVelGain * vy;
  if (!isFinite(heightExtra)) heightExtra = 0;
  if (heightExtra > 80) heightExtra = 80;
  if (heightExtra < -80) heightExtra = -80;

  tauKA += heightExtra * wA;
  tauKB += heightExtra * wB;

  tauHA += directHip * Math.sin(TWOPI * qA + phaseSin) * ramp;
  tauHB += directHip * Math.sin(TWOPI * qB + phaseSin) * ramp;
  tauKA += directKnee * Math.sin(TWOPI * qA + phaseSin) * ramp;
  tauKB += directKnee * Math.sin(TWOPI * qB + phaseSin) * ramp;

  if (footA > 0.5) {
    tauKA += contactStraight * (-0.052 - kneeA);
  }
  if (footB > 0.5) {
    tauKB += contactStraight * (-0.052 - kneeB);
  }

  if (height < 0.62 && recoverGain > 0) {
    const rec = recoverGain * (0.62 - height);
    tauKA += rec;
    tauKB += rec;
  }

  function sat(v) {
    if (!isFinite(v)) return 0;
    if (v > 1) return 1;
    if (v < -1) return -1;
    return v;
  }

  return [sat(tauHA), sat(tauKA), sat(tauHB), sat(tauKB)];
}

function learn(lab) {
  const N = DEF.length;
  let used = 0;
  let trialLength = 10;
  const TIME_LIMIT = 165000;

  let startTime = 0;
  try {
    if (typeof Date !== "undefined" && Date.now) startTime = Date.now();
  } catch (e) {
    startTime = 0;
  }

  function timeUp() {
    if (!startTime) return false;
    try {
      return (Date.now() - startTime) > TIME_LIMIT;
    } catch (e) {
      return false;
    }
  }

  try {
    if (lab && typeof lab.seconds === "number" && lab.seconds > 1) trialLength = lab.seconds;
  } catch (e) {}

  function left() {
    try {
      const l = lab.trialsLeft();
      if (typeof l === "number" && isFinite(l)) return l;
    } catch (e) {}
    let total = 1000;
    try {
      if (lab && typeof lab.trials === "number") total = lab.trials;
    } catch (e) {}
    return Math.max(0, total - used);
  }

  function clamp01(v) {
    if (v < 0) return 0;
    if (v > 1) return 1;
    return v;
  }

  function makeX(src) {
    const x = new Array(N);
    for (let i = 0; i < N; i++) {
      let v = src && typeof src[i] === "number" ? src[i] : DEF[i];
      if (!isFinite(v)) v = DEF[i];
      if (v < LB[i]) v = LB[i];
      if (v > UB[i]) v = UB[i];
      x[i] = v;
    }
    return x;
  }

  function normX(x) {
    const z = new Array(N);
    for (let i = 0; i < N; i++) {
      let v = x && typeof x[i] === "number" ? x[i] : DEF[i];
      if (!isFinite(v)) v = DEF[i];
      z[i] = clamp01((v - LB[i]) / (UB[i] - LB[i]));
    }
    return z;
  }

  function denorm(z) {
    const x = new Array(N);
    for (let i = 0; i < N; i++) {
      let u = z[i];
      if (!isFinite(u)) u = 0.5;
      u = clamp01(u);
      x[i] = LB[i] + (UB[i] - LB[i]) * u;
    }
    return x;
  }

  function gauss() {
    let u = 0;
    while (u === 0) u = Math.random();
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  let bestOverall = null;
  let bestFinished = null;
  let bestFellFar = null;
  const records = [];

  function evalX(src) {
    if (left() <= 0 || timeUp()) {
      return {
        x: makeX(src), fit: -1e100, d: 0, outcome: "error",
        time: 0, energy: 0
      };
    }

    const xx = makeX(src);
    let r = null;
    try {
      r = lab.trial(xx);
    } catch (e) {
      r = null;
    }
    used++;

    let d = 0;
    let tm = 0;
    let outcome = "error";
    let energy = 0;

    if (r) {
      d = Number(r.distance);
      if (!isFinite(d) || d < 0) d = 0;
      tm = Number(r.time);
      if (!isFinite(tm) || tm < 0) tm = 0;
      outcome = String(r.outcome || "error");
      energy = Number(r.energy);
      if (!isFinite(energy)) energy = 0;
    }

    let fit;
    if (outcome === "finished") {
      fit = d + 2.0 + 0.02 * tm;
    } else if (outcome === "fell") {
      fit = d - 0.08 * Math.max(0, trialLength - tm);
    } else {
      fit = -100000 + d;
    }

    const rec = {
      x: xx,
      fit: fit,
      d: d,
      outcome: outcome,
      time: tm,
      energy: energy
    };

    records.push(rec);
    if (records.length > 600) {
      records.sort(function (a, b) { return b.fit - a.fit; });
      records.length = 400;
    }

    if (!bestOverall || rec.fit > bestOverall.fit) bestOverall = rec;
    if (outcome === "finished") {
      if (!bestFinished || rec.d > bestFinished.d ||
          (Math.abs(rec.d - bestFinished.d) < 1e-9 && rec.fit > bestFinished.fit)) {
        bestFinished = rec;
      }
    }
    if (outcome === "fell" && rec.d > 0.5) {
      if (!bestFellFar || rec.fit > bestFellFar.fit) bestFellFar = rec;
    }

    return rec;
  }

  const seeds = [];
  function addSeed(fn) {
    const a = DEF.slice();
    if (fn) fn(a);
    seeds.push(makeX(a));
  }

  addSeed(null);

  addSeed(function (a) {
    a[0] = 1.45; a[1] = 0.64; a[4] = 0.38; a[5] = 0.835;
    a[6] = 0.025; a[7] = 0.14; a[13] = -0.03; a[14] = 4.5;
    a[16] = 0.5; a[17] = 0.9; a[18] = 0.65; a[21] = 1.10;
    a[22] = 7.0; a[28] = 0.25;
  });

  addSeed(function (a) {
    a[0] = 2.15; a[1] = 0.54; a[4] = 0.72; a[5] = 0.842;
    a[6] = 0.050; a[7] = 0.25; a[13] = -0.12; a[14] = 7.0;
    a[15] = 1.2; a[16] = 1.0; a[17] = 2.3; a[18] = 0.75;
    a[19] = 0.10; a[20] = 0.35; a[22] = 9.0;
  });

  addSeed(function (a) {
    a[0] = 1.70; a[1] = 0.57; a[4] = 0.48; a[5] = 0.866;
    a[6] = 0.0; a[7] = 0.08; a[13] = -0.05; a[14] = 5.0;
    a[16] = 0.7; a[17] = 1.2; a[18] = 0.8; a[22] = 10.0;
    a[36] = 1.0;
  });

  addSeed(function (a) {
    a[0] = 1.60; a[1] = 0.42; a[2] = 0.0; a[4] = 0.35;
    a[5] = 0.835; a[6] = 0.04; a[7] = 0.28; a[13] = -0.07;
    a[14] = 5.0; a[16] = 0.6; a[17] = 1.0; a[18] = 0.50;
    a[22] = 6.0;
  });

  addSeed(function (a) {
    a[0] = 1.20; a[1] = 0.66; a[4] = 0.30; a[5] = 0.82;
    a[7] = 0.10; a[13] = -0.02; a[17] = 0.55; a[22] = 6.0;
  });

  addSeed(function (a) {
    a[0] = 2.40; a[1] = 0.50; a[4] = 0.85; a[5] = 0.850;
    a[6] = 0.06; a[7] = 0.30; a[13] = -0.16; a[14] = 8.0;
    a[15] = 1.5; a[16] = 1.2; a[17] = 2.8; a[18] = 0.80;
    a[9] = 10.0; a[11] = 13.0;
  });

  addSeed(function (a) {
    a[3] = 0.25;
    a[4] = 0.55; a[17] = 1.4;
  });

  addSeed(function (a) {
    a[3] = 0.50;
    a[4] = 0.55; a[17] = 1.4;
  });

  addSeed(function (a) {
    a[3] = 0.75;
    a[4] = 0.55; a[17] = 1.4;
  });

  addSeed(function (a) {
    a[14] = 3.5; a[15] = 0.5; a[16] = 0.4; a[13] = -0.04;
    a[17] = 0.9; a[4] = 0.42; a[22] = 5.0;
  });

  addSeed(function (a) {
    a[14] = 8.0; a[15] = 1.5; a[16] = 1.2; a[13] = -0.10;
    a[17] = 1.8; a[4] = 0.65; a[22] = 10.0;
  });

  addSeed(function (a) {
    a[14] = 10.0; a[15] = 2.0; a[16] = 1.5; a[13] = -0.18;
    a[17] = 2.4; a[4] = 0.75; a[22] = 12.0; a[9] = 10.0;
  });

  addSeed(function (a) {
    a[24] = 0.40; a[25] = 0.25; a[26] = 8.0; a[27] = 0.10;
  });

  addSeed(function (a) {
    a[29] = 20.0; a[36] = 1.0;
  });

  addSeed(function (a) {
    a[6] = 0.10; a[7] = 0.18; a[5] = 0.84; a[22] = 10.0;
  });

  for (let i = 0; i < 18; i++) {
    const a = DEF.slice();
    const scale = 0.18;
    for (let j = 0; j < N; j++) {
      if (Math.random() < 0.18) {
        a[j] = LB[j] + Math.random() * (UB[j] - LB[j]);
      } else {
        a[j] += gauss() * scale * (UB[j] - LB[j]);
      }
    }
    seeds.push(makeX(a));
  }

  for (let si = 0; si < seeds.length; si++) {
    if (left() <= 5 || timeUp()) break;
    evalX(seeds[si]);
  }

  function runES(centerRec, budget, sigma0, localMode) {
    if (budget < 6 || left() <= 3 || timeUp()) return;
    const centerX = centerRec && centerRec.x ? makeX(centerRec.x) : makeX(DEF);
    let mean = normX(centerX);
    const sig = new Array(N);
    for (let i = 0; i < N; i++) {
      sig[i] = sigma0;
      if (localMode) {
        if (i === 0) sig[i] = 0.025;
        if (i === 5) sig[i] = 0.018;
        if (i === 4) sig[i] = 0.035;
        if (i === 13) sig[i] = 0.025;
        if (i === 14) sig[i] = 0.035;
        if (i === 17) sig[i] = 0.035;
      } else {
        if (i === 2) sig[i] = sigma0 * 0.15;
        if (i === 5) sig[i] = sigma0 * 0.35;
        if (i === 9 || i === 11) sig[i] = sigma0 * 0.65;
      }
    }

    const startUsed = used;
    let gen = 0;
    let noImp = 0;
    let localBestFit = -1e100;

    while ((used - startUsed) < budget && left() > 2 && !timeUp()) {
      const remain = budget - (used - startUsed);
      let popSize = localMode ? 16 : 26;
      if (popSize > remain) popSize = remain;
      if (popSize > left()) popSize = left();
      if (popSize < 5) break;

      const pop = [];

      for (let k = 0; k < popSize; k++) {
        if (left() <= 0 || timeUp()) break;

        let z;
        if (k === 0) {
          z = mean.slice();
        } else if (k === 1 && bestOverall) {
          z = normX(bestOverall.x);
        } else if (k === 2 && bestFinished) {
          z = normX(bestFinished.x);
        } else if (k === 3 && bestFellFar && !localMode) {
          z = normX(bestFellFar.x);
        } else {
          z = new Array(N);
          const globalRand = !localMode && Math.random() < (gen < 3 ? 0.10 : 0.018);
          for (let i = 0; i < N; i++) {
            if (globalRand && i !== 2) {
              z[i] = Math.random();
            } else {
              let val = mean[i] + sig[i] * gauss();
              z[i] = clamp01(val);
            }
          }
        }

        if (localMode) {
          if (z[2] < 0.35 && z[2] > 0.15) z[2] = 0.5;
        }

        const rec = evalX(denorm(z));
        pop.push({ z: z, rec: rec });
      }

      if (pop.length < 5) break;

      pop.sort(function (a, b) { return b.rec.fit - a.rec.fit; });

      if (pop[0].rec.fit > localBestFit) {
        localBestFit = pop[0].rec.fit;
        noImp = 0;
      } else {
        noImp++;
      }

      let K = Math.floor(pop.length * (localMode ? 0.25 : 0.22));
      if (K < 3) K = 3;
      if (K > pop.length) K = pop.length;

      const m = new Array(N);
      const v = new Array(N);

      for (let i = 0; i < N; i++) {
        let sumW = 0;
        let mi = 0;
        for (let j = 0; j < K; j++) {
          const w = Math.exp(-0.35 * j);
          mi += w * pop[j].z[i];
          sumW += w;
        }
        mi /= sumW;

        let vv = 0;
        for (let j = 0; j < K; j++) {
          const w = Math.exp(-0.35 * j);
          const di = pop[j].z[i] - mi;
          vv += w * di * di;
        }
        vv /= sumW;

        m[i] = mi;
        v[i] = vv;
      }

      const blend = localMode ? 0.55 : 0.42;

      for (let i = 0; i < N; i++) {
        mean[i] = (1 - blend) * mean[i] + blend * m[i];

        let ns = Math.sqrt(v[i]);
        ns = (1 - blend) * sig[i] + blend * ns;

        const floor = localMode ? 0.006 : 0.010;
        let cap = localMode ? 0.12 : 0.50;
        if (i === 2) cap = Math.min(cap, 0.08);
        if (i === 5) cap = Math.min(cap, 0.10);

        if (ns < floor) ns = floor;
        if (ns > cap) ns = cap;
        sig[i] = ns;
      }

      if (noImp > (localMode ? 5 : 9) && gen > 2) {
        let cen = bestFinished || bestOverall;
        if (cen && cen.x) {
          const zc = normX(cen.x);
          for (let i = 0; i < N; i++) {
            mean[i] = 0.65 * mean[i] + 0.35 * zc[i];
            if (sig[i] < (localMode ? 0.03 : 0.12)) {
              sig[i] = localMode ? 0.03 : 0.12;
            }
          }
        } else {
          for (let i = 0; i < N; i++) {
            mean[i] = 0.5 * mean[i] + 0.5 * Math.random();
            if (sig[i] < 0.18) sig[i] = 0.18;
          }
        }
        noImp = 0;
      }

      gen++;
      if (localMode && gen > 14) break;
    }
  }

  let rem = left();
  if (rem > 120 && !timeUp()) {
    let b = Math.min(470, rem - 90);
    runES(bestFinished || bestOverall, b, 0.24, false);
  }

  rem = left();
  if (rem > 70 && !timeUp()) {
    let b = Math.min(220, rem - 50);
    runES(bestOverall, b, 0.16, false);
  }

  rem = left();
  if (rem > 45 && !timeUp()) {
    let b = Math.min(210, rem - 25);
    runES(bestFinished || bestOverall, b, 0.065, true);
  }

  rem = left();
  if (rem > 12 && !timeUp()) {
    let b = Math.min(100, rem - 5);
    runES(bestOverall, b, 0.045, true);
  }

  rem = left();
  let tries = 0;
  while (rem > 1 && used < 998 && !timeUp() && tries < 40) {
    const base = bestFinished || bestOverall;
    if (!base || !base.x) {
      evalX(DEF);
    } else {
      const z = normX(base.x);
      for (let i = 0; i < N; i++) {
        if (Math.random() < 0.35) {
          z[i] = clamp01(z[i] + gauss() * (i === 2 ? 0.02 : 0.045));
        }
      }
      evalX(denorm(z));
    }
    rem = left();
    tries++;
  }

  let chosen = bestOverall;

  if (bestFinished) {
    if (!chosen || chosen.outcome !== "finished") {
      if (!chosen || chosen.outcome === "invalid" || chosen.outcome === "error" ||
          bestFinished.d >= chosen.d * 0.72) {
        chosen = bestFinished;
      }
    } else if (bestFinished.d >= chosen.d * 0.98 && bestFinished.fit >= chosen.fit - 0.4) {
      chosen = bestFinished;
    }
  }

  if ((!chosen || !chosen.x) && bestFellFar) chosen = bestFellFar;
  if (!chosen || !chosen.x) chosen = { x: makeX(DEF) };

  return makeX(chosen.x);
}

const DEF = [
  1.60, 0.58, 0.50, 0.00, 0.50, 0.00, 0.12, 0.75,
  0.10, 5.0, 0.60, 10.0, 1.00, 3.0, 1.0, 0.60,
  1.30, 1.08, 15.0, 1.00, -1.00, -0.20, 0.20, 0.60,
  0.30, 1.00, -0.05, 1.00, 0.00, 0.30, 2.00
];

const LB = [
  0.50, 0.35, 0.00, -1.00, 0.10, -0.40, 0.02, 0.00,
  0.00, 1.00, 0.00, 2.00, 0.00, -5.0, -5.0, -2.00,
  0.00, 0.65, 0.00, 0.00, -4.00, -4.00, -4.00, 0.00,
  -1.00, 0.00, -0.50, 0.00, -3.00, 0.02, -5.00
];

const UB = [
  3.20, 0.80, 1.00, 1.00, 1.00, 0.50, 0.70, 1.40,
  0.80, 30.0, 5.0, 60.0, 8.0, 25.0, 15.0, 6.0,
  4.0, 1.30, 60.0, 15.0, 4.0, 4.0, 4.0, 2.0,
  2.0, 1.00, 0.30, 1.50, 3.00, 1.50, 15.0
];

function policy(obs, params, mem) {
  const PI = Math.PI;
  const TWOPI = 2 * PI;

  let p = params;
  if (!p || typeof p.length !== "number" || p.length < DEF.length) p = DEF;

  function get(i) {
    let v = p[i];
    if (typeof v !== "number" || !isFinite(v)) v = DEF[i];
    if (v < LB[i]) v = LB[i];
    if (v > UB[i]) v = UB[i];
    return v;
  }

  const freq = get(0);
  const duty = get(1);
  const legOff = get(2);
  const phase0 = get(3);
  const hipAmp = get(4);
  const hipBias = get(5);
  const kneeStance = get(6);
  const kneeLift = get(7);
  const stanceFlex = get(8);

  const hKp = get(9);
  const hKd = get(10);
  const kKp = get(11);
  const kKd = get(12);

  const balTheta = get(13);
  const balSpin = get(14);
  const balVel = get(15);
  const targetVx = get(16);

  const heightTarget = get(17);
  const heightGain = get(18);
  const heightVelGain = get(19);

  const placeTheta = get(20);
  const placeSpin = get(21);
  const placeVel = get(22);
  const obstacleLift = get(23);
  const obstacleHip = get(24);
  const contactW = get(25);
  const leanTarget = get(26);
  const comp = get(27);
  const pushGain = get(28);
  const startRamp = get(29);
  const contactStraight = get(30);

  const theta = +obs[0] || 0;
  const spin = +obs[1] || 0;
  const vx = +obs[2] || 0;
  const vy = +obs[3] || 0;
  const height = +obs[4] || 0;
  const t = +obs[19] || 0;

  const hipAcur = +obs[5] || 0;
  const hipAs = +obs[6] || 0;
  const kneeAcur = +obs[7] || 0;
  const kneeAs = +obs[8] || 0;
  let footA = +obs[9] || 0;
  if (footA < 0) footA = 0;
  if (footA > 1) footA = 1;

  const hipBcur = +obs[10] || 0;
  const hipBs = +obs[11] || 0;
  const kneeBcur = +obs[12] || 0;
  const kneeBs = +obs[13] || 0;
  let footB = +obs[14] || 0;
  if (footB < 0) footB = 0;
  if (footB > 1) footB = 1;

  const a1 = +obs[15] || 0;
  const a2 = +obs[16] || 0;
  const a3 = +obs[17] || 0;
  const a4 = +obs[18] || 0;

  if (!mem || typeof mem !== "object") mem = {};

  let rawOh = Math.max(0, a1 * 0.90, a2 * 0.75, a3 * 0.45, a4 * 0.20);
  if (!isFinite(rawOh) || rawOh < 0) rawOh = 0;
  if (rawOh > 0.9) rawOh = 0.9;
  if (typeof mem.oh !== "number" || !isFinite(mem.oh)) mem.oh = rawOh;
  else mem.oh += 0.26 * (rawOh - mem.oh);
  let oh = mem.oh;
  if (!isFinite(oh) || oh < 0) oh = 0;
  if (oh > 0.9) oh = 0.9;

  let ramp = 1;
  if (startRamp > 0.001 && t < startRamp) {
    let u = t / startRamp;
    if (u < 0) u = 0;
    if (u > 1) u = 1;
    ramp = u * u * (3 - 2 * u);
  }

  const common = balTheta * (theta - leanTarget) + balSpin * spin + balVel * (targetVx - vx);

  let hErr = heightTarget - height;
  if (hErr < 0) hErr = 0;
  let hExtra = heightGain * hErr - heightVelGain * vy;
  if (!isFinite(hExtra) || hExtra < 0) hExtra = 0;

  function frac(v) {
    return v - Math.floor(v);
  }

  function makeLeg(q, hipNow, kneeNow, hipSpeed, kneeSpeed, footNow) {
    let stance = q < duty;
    let u = 0;
    let s = 0;
    let k = -kneeStance;

    if (stance) {
      u = q / duty;
      if (u < 0) u = 0;
      if (u > 1) u = 1;
      s = hipBias + hipAmp * ramp * (1 - 2 * u);
      k = -kneeStance - stanceFlex * ramp * Math.sin(PI * u);
    } else {
      u = (q - duty) / (1 - duty);
      if (u < 0) u = 0;
      if (u > 1) u = 1;

      let u2 = u * u * (3 - 2 * u);
      s = hipBias + hipAmp * ramp * (-1 + 2 * u2);

      let place = placeTheta * (theta - leanTarget) +
                  placeSpin * spin +
                  placeVel * (vx - targetVx);
      if (!isFinite(place)) place = 0;

      s += place * u2 * ramp;

      k = -kneeStance - kneeLift * ramp * Math.pow(Math.sin(PI * u), 1.15);

      if (oh > 0.0001) {
        let occ = oh * (0.25 + 0.75 * Math.sin(PI * u));
        s += obstacleHip * occ * ramp;
        k -= obstacleLift * occ * ramp;
      }
    }

    let hT = s - comp * theta;
    if (hT < -0.889) hT = -0.889;
    if (hT > 1.199) hT = 1.199;
    if (k < -1.69) k = -1.69;
    if (k > -0.052) k = -0.052;

    let tauH = hKp * (hT - hipNow) - hKd * hipSpeed;
    let tauK = kKp * (k - kneeNow) - kKd * kneeSpeed;

    let w = (1 - contactW) + contactW * footNow;
    if (w < 0) w = 0;
    if (w > 1) w = 1;

    tauH += common * w;

    if (stance) {
      tauH += pushGain * ramp * (0.5 - u);
    }

    tauK += hExtra * w;

    if (footNow > 0.5) {
      let straight = -kneeStance - kneeNow;
      if (straight > 0) tauK += contactStraight * straight;
    }

    return [tauH, tauK];
  }

  let phase = phase0 + freq * t;
  let qA = frac(phase);
  let qB = frac(phase + legOff);

  let outA = makeLeg(qA, hipAcur, kneeAcur, hipAs, kneeAs, footA);
  let outB = makeLeg(qB, hipBcur, kneeBcur, hipBs, kneeBs, footB);

  function sat(v) {
    if (!isFinite(v)) return 0;
    if (v > 1) return 1;
    if (v < -1) return -1;
    return v;
  }

  return [sat(outA[0]), sat(outA[1]), sat(outB[0]), sat(outB[1])];
}

function learn(lab) {
  const N = DEF.length;
  let used = 0;

  let startTime = 0;
  try {
    if (typeof Date !== "undefined" && Date.now) startTime = Date.now();
  } catch (e) {
    startTime = 0;
  }

  function timeUp() {
    if (!startTime) return false;
    try {
      return (Date.now() - startTime) > 168000;
    } catch (e) {
      return false;
    }
  }

  function left() {
    try {
      const l = lab.trialsLeft();
      if (typeof l === "number" && isFinite(l)) return l;
    } catch (e) {}
    let total = 1000;
    try {
      if (lab && typeof lab.trials === "number" && isFinite(lab.trials)) total = lab.trials;
    } catch (e) {}
    return Math.max(0, total - used);
  }

  function clamp01(v) {
    if (!isFinite(v)) return 0.5;
    if (v < 0) return 0;
    if (v > 1) return 1;
    return v;
  }

  function makeX(src) {
