  addSeed(function(a) {
    a[2] = 0.62; a[0] = 1.70; a[1] = 0.55; a[4] = 0.50;
    a[16] = 1.5; a[20] = -0.8;
  });

  for (let r = 0; r < 18; r++) {
    const z = normX(DEF);
    for (let i = 0; i < N; i++) {
      if (Math.random() < 0.28) {
        z[i] = clamp01(z[i] + gauss() * (0.07 + Math.random() * 0.18));
      }
    }
    seeds.push(denormZ(z));
  }

  for (let si = 0; si < seeds.length; si++) {
    if (left() <= 5 || timeUp()) break;
    evalX(seeds[si]);
  }

  runCEM(bestOverall || { x: DEF }, 255, 0.22, false);
  runCEM(bestFinished || bestOverall || { x: DEF }, 225, 0.14, false);
  runCEM(bestOverall || bestFinished || { x: DEF }, 205, 0.095, true);
  runCEM(bestFinished || bestOverall || { x: DEF }, 150, 0.055, true);

  let iterations = 0;
  while (left() > 1 && used < 995 && !timeUp() && iterations < 80) {
    let base = null;
    if (bestFinished && Math.random() < 0.68) base = bestFinished.x;
    else if (bestOverall) base = bestOverall.x;
    else if (bestValidDistance) base = bestValidDistance.x;
    else base = DEF;

    const z = normX(base);
    let scale = 0.025 + Math.random() * 0.095;

    for (let i = 0; i < N; i++) {
      if (Math.random() < 0.30) {
        z[i] = clamp01(z[i] + gauss() * scale);
      }
    }

    evalZ(z);
    iterations++;
  }

  let chosen = bestFinished;

  if (!chosen) chosen = bestOverall;
  if (!chosen) chosen = bestValidDistance;
  if (!chosen || !chosen.x) chosen = { x: makeX(DEF) };

  if (bestFinished && bestOverall && bestOverall !== bestFinished) {
    if (bestOverall.outcome !== "invalid" && bestOverall.outcome !== "error") {
      if (bestOverall.d > Math.max(2.5, bestFinished.d * 1.60)) {
        chosen = bestOverall;
      }
    }
  }

  return makeX(chosen.x);
}

