    return [
      hx + L1 * Math.cos(a1) + L2 * Math.cos(a2),
      hy + L1 * Math.sin(a1) + L2 * Math.sin(a2)
    ];
  }

  function makeLeg(q, hipNow, kneeNow, hipSpeed, kneeSpeed, footNow) {
    let stance = q < duty;
    let u = 0;
    let s = 0;
    let k = -kneeStance;

    if (stance) {
      u = q / duty;
      if (u < 0) u = 0;
      if (u > 1) u = 1;
      s = hipBias + hipAmp * ramp * (1 - 2 * u);
      k = -kneeStance - stanceFlex * ramp * Math.sin(PI * u);
      k += kneeExtendBias * ramp;
    } else {
      u = (q - duty) / (1 - duty);
      if (u < 0) u = 0;
      if (u > 1) u = 1;

      let u2 = u * u * (3 - 2 * u);
      s = hipBias + hipAmp * ramp * (-1 + 2 * u2);

      let place = placeTheta * (theta - leanUse) +
                  placeSpin * spin +
                  placeVel * (vx - targetVx);
      if (!isFinite(place)) place = 0;
      s += place * u2 * ramp;
      s += swingHipExtra * Math.sin(PI * u) * ramp;

      k = -kneeStance - kneeLift * ramp * Math.pow(Math.sin(PI * u), 1.15);
      k += swingKneeTarget * Math.sin(PI * u) * ramp;

      if (oh > 0.0001) {
        let occ = oh * (0.25 + 0.75 * Math.sin(PI * u));
        s += obstacleHip * occ * ramp;
        k -= obstacleLift * occ * ramp;
      }
    }

    if (!stance && clearGain > 0 && footNow < 0.5) {
      const fp = footPos(hipNow, kneeNow);
      const gy = terrainAt(fp[0]);
      let desired = clearHeight + 0.55 * oh;
      if (desired > 0.75) desired = 0.75;
      const clear = fp[1] - gy;
      if (clear < desired) {
        k -= clearGain * (desired - clear);
      }
    }

    let hT = s - comp * theta;
    if (hT < -0.889) hT = -0.889;
    if (hT > 1.199) hT = 1.199;
    if (k < -1.69) k = -1.69;
    if (k > -0.052) k = -0.052;

    let tauH = hKp * (hT - hipNow) - hKd * hipSpeed;
    let tauK = kKp * (k - kneeNow) - kKd * kneeSpeed;

    let w = (1 - contactW) + contactW * footNow;
    if (w < 0) w = 0;
    if (w > 1) w = 1;

    tauH += common * w;

    if (stance) {
      tauH += pushGain * ramp * (0.5 - u);
      if (stanceHipFf !== 0) {
        tauH += stanceHipFf * Math.sin(PI * u + stanceHipFfPhase) * ramp;
      }
      if (stanceKneePush !== 0) {
        let sh = Math.sin(PI * u);
        if (sh < 0) sh = 0;
        tauK += stanceKneePush * Math.pow(sh, stanceKneePushPow) * ramp;
      }
      if (lateHipPush !== 0) {
        let late = (u - 0.55) / 0.45;
        if (late > 0) tauH += lateHipPush * late * ramp;
      }
    } else if (swingKneeTorque !== 0) {
      tauK += swingKneeTorque * Math.sin(PI * u) * ramp;
    }

    tauK += hExtra * w;

    if (footNow > 0.5) {
      let straight = -kneeStance - kneeNow;
      if (straight > 0) tauK += contactStraight * straight;
    }

    if (emergencyKnee !== 0) {
      let low = 1.00 - height;
      if (low > 0) {
        tauK += emergencyKnee * low * (0.35 + 0.65 * footNow);
      }
    }

    if (emergencyHip !== 0) {
      let le = theta - leanUse;
      tauH += emergencyHip * (le + 0.08 * spin) * (0.35 + 0.65 * footNow);
    }

    return [tauH, tauK];
  }

  const phaseOffset = phaseDist * mem.dist + phaseVxGain * mem.vxTime + obstaclePhaseLead * oh;
  const phase = phase0 + freq * t + phaseOffset;
  const qA = frac(phase);
  const qB = frac(phase + legOff);

  const outA = makeLeg(qA, hipAcur, kneeAcur, hipAs, kneeAs, footA);
  const outB = makeLeg(qB, hipBcur, kneeBcur, hipBs, kneeBs, footB);

  function sat(v) {
    if (!isFinite(v)) return 0;
    if (v > 1) return 1;
    if (v < -1) return -1;
    return v;
  }

  return [sat(outA[0]), sat(outA[1]), sat(outB[0]), sat(outB[1])];
}

function policy(obs, params, mem) {
  if (!mem || typeof mem !== "object") mem = {};
  if (!mem.main) mem.main = {};
  if (!mem.safe) mem.safe = {};

  let p = params;
  if (!p || typeof p.length !== "number") p = DEF;

  const outMain = calc(obs, p, mem.main);
  const outSafe = calc(obs, P5, mem.safe);

  const t = +obs[19] || 0;
  const theta = +obs[0] || 0;
  const spin = +obs[1] || 0;
  const height = +obs[4] || 0;

  let risk = 0;
  if (height < 0.62) risk += (0.62 - height) * 6.0;
  if (height < 0.45) risk += (0.45 - height) * 12.0;
  const ab = Math.abs(theta);
  if (ab > 0.55) risk += (ab - 0.55) * 4.0;
  const asp = Math.abs(spin);
  if (asp > 6.0) risk += (asp - 6.0) * 0.10;
  if (!isFinite(risk) || risk < 0) risk = 0;

  if (typeof mem.bad !== "number" || !isFinite(mem.bad)) mem.bad = 0;
  if (risk > 0.02) {
    mem.bad += 0.08 + 0.05 * risk;
    if (mem.bad > 1) mem.bad = 1;
  } else {
    mem.bad -= 0.006;
    if (mem.bad < 0) mem.bad = 0;
  }

  let w = mem.bad;
  if (t > 10.2) {
    let minW = 0.05 + 0.10 * Math.min(1, (t - 10.2) / 5.0);
    if (w < minW) w = minW;
  }
  if (w < 0) w = 0;
  if (w > 1) w = 1;
  if (w <= 0.00001) return outMain;
  if (w >= 0.99999) return outSafe;

  const out = [0, 0, 0, 0];
  for (let i = 0; i < 4; i++) out[i] = (1 - w) * outMain[i] + w * outSafe[i];
  return out;
}

function learn(lab) {
  const TIME_LIMIT = 160000;
  let startTime = 0;
  try {
    if (typeof Date !== "undefined" && Date.now) startTime = Date.now();
  } catch (e) {
    startTime = 0;
  }

  function timeUp() {
    if (!startTime) return false;
    try {
      return (Date.now() - startTime) > TIME_LIMIT;
    } catch (e) {
      return false;
    }
  }

  let used = 0;
  function left() {
    try {
      const l = lab.trialsLeft();
      if (typeof l === "number" && isFinite(l)) return l;
    } catch (e) {}
    let total = 1000;
    try {
      if (lab && typeof lab.trials === "number" && isFinite(lab.trials)) total = lab.trials;
    } catch (e) {}
    return Math.max(0, total - used);
  }

  function clamp01(v) {
    if (!isFinite(v)) return 0.5;
    if (v < 0) return 0;
    if (v > 1) return 1;
    return v;
  }

  function makeX(src) {
    const x = new Array(N);
    for (let i = 0; i < N; i++) {
      let v = src && typeof src[i] === "number" ? src[i] : DEF[i];
      if (!isFinite(v)) v = DEF[i];
      if (v < LB[i]) v = LB[i];
      if (v > UB[i]) v = UB[i];
      x[i] = v;
    }
    return x;
  }

  function normX(x) {
    const z = new Array(N);
    for (let i = 0; i < N; i++) {
      let v = x && typeof x[i] === "number" ? x[i] : DEF[i];
      if (!isFinite(v)) v = DEF[i];
      if (v < LB[i]) v = LB[i];
      if (v > UB[i]) v = UB[i];
      z[i] = clamp01((v - LB[i]) / (UB[i] - LB[i]));
    }
    return z;
  }

  function denormZ(z) {
    const x = new Array(N);
    for (let i = 0; i < N; i++) {
      let u = z && z[i];
      if (!isFinite(u)) u = 0.5;
      u = clamp01(u);
      x[i] = LB[i] + (UB[i] - LB[i]) * u;
    }
    return x;
  }

  function gauss() {
    let u = 0;
    while (u === 0) u = Math.random();
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  }

  let bestOverall = null;
  let bestFinished = null;
  let bestValidDistance = null;
  const records = [];

  function evalX(src) {
    if (left() <= 0 || used >= 998 || timeUp()) {
      return {
        x: makeX(src),
        fit: -1e100,
        d: 0,
        outcome: "error",
        time: 0,
        energy: 0,
        dummy: true
      };
    }

    const xx = makeX(src);
    let r = null;
    try {
      r = lab.trial(xx);
    } catch (e) {
      r = null;
    }
    used++;

    let d = 0;
    let tm = 0;
    let outcome = "error";
    let energy = 0;

    if (r) {
      d = Number(r.distance);
      if (!isFinite(d) || d < 0) d = 0;
      tm = Number(r.time);
      if (!isFinite(tm) || tm < 0) tm = 0;
      outcome = String(r.outcome || "error");
      energy = Number(r.energy);
      if (!isFinite(energy)) energy = 0;
    }

    let fit;
    if (outcome === "finished") {
      fit = 1.95 * d + 0.20;
    } else if (outcome === "fell") {
      fit = d;
    } else if (outcome === "invalid") {
      fit = -100000 + d;
    } else {
      fit = -1000000 + d;
    }

    const rec = {
      x: xx,
      fit: fit,
      d: d,
      outcome: outcome,
      time: tm,
      energy: energy
    };

    records.push(rec);

    if (!bestOverall || rec.fit > bestOverall.fit) bestOverall = rec;

    if (outcome === "finished") {
      if (!bestFinished || rec.fit > bestFinished.fit) bestFinished = rec;
    }

    if (outcome === "finished" || outcome === "fell") {
      if (!bestValidDistance || rec.d > bestValidDistance.d) bestValidDistance = rec;
    }

    return rec;
  }

  function runCEM(centerX, budget, sigma0, mode) {
    if (left() <= 5 || timeUp()) return null;
    let mean = normX(makeX(centerX));
    const sig = new Array(N);

    for (let i = 0; i < N; i++) {
      let mult = 1;
      if (mode === "p5extra") {
        mult = (i < 31) ? 0.18 : 1.0;
        if (i === 0 || i === 1 || i === 2) mult *= 0.5;
        if (i === 3) mult = 0.08;
        if (i === 16 || i === 17 || i === 18) mult *= 0.7;
      } else if (mode === "local") {
        mult = 0.60;
      } else if (mode === "refine") {
        mult = (i < 31) ? 0.80 : 1.0;
      } else if (mode === "run") {
        mult = (i < 31) ? 1.0 : 0.80;
      }
      let s = sigma0 * mult;
      if (i === 3) s *= 0.5;
      if (s < 0.004) s = 0.004;
      sig[i] = s;
    }

    const startUsed = used;
    let gen = 0;
    let noImp = 0;
    let localBestFit = -1e100;

    while ((used - startUsed) < budget && left() > 4 && !timeUp()) {
      const remain = budget - (used - startUsed);
      let popSize = (mode === "local") ? 16 : (mode === "p5extra" ? 20 : 24);
      if (popSize > remain) popSize = remain;
      if (popSize > left() - 1) popSize = left() - 1;
      if (popSize < 5) break;

      const pop = [];

      for (let k = 0; k < popSize; k++) {
        if (left() <= 1 || timeUp()) break;

        let z;
        if (k === 0) {
          z = mean.slice();
        } else if (k === 1 && bestOverall) {
          z = normX(bestOverall.x);
        } else if (k === 2 && bestFinished) {
          z = normX(bestFinished.x);
        } else if (k === 3 && bestValidDistance && mode !== "local") {
          z = normX(bestValidDistance.x);
        } else {
          z = new Array(N);
          const globalRand = (mode === "global" || mode === "run") &&
                             Math.random() < (gen < 3 ? 0.12 : 0.02);
          for (let i = 0; i < N; i++) {
            if (globalRand && i !== 2 && i !== 3 && Math.random() < 0.5) {
              z[i] = Math.random();
            } else {
              z[i] = clamp01(mean[i] + sig[i] * gauss());
            }
          }
        }

        const rec = evalX(denormZ(z));
        pop.push({ z: z, rec: rec });
      }

      if (pop.length < 5) break;

      pop.sort(function (a, b) { return b.rec.fit - a.rec.fit; });

      if (pop[0].rec.fit > localBestFit) {
        localBestFit = pop[0].rec.fit;
        noImp = 0;
      } else {
        noImp++;
      }

      let K = Math.floor(pop.length * (mode === "local" ? 0.30 : 0.24));
      if (K < 3) K = 3;
      if (K > pop.length) K = pop.length;

      const m = new Array(N);
      const v = new Array(N);

      for (let i = 0; i < N; i++) {
        let sumW = 0;
        let mi = 0;
        for (let j = 0; j < K; j++) {
          const w = Math.exp(-0.40 * j);
          mi += w * pop[j].z[i];
          sumW += w;
        }
        mi /= sumW;

        let vv = 0;
        for (let j = 0; j < K; j++) {
          const w = Math.exp(-0.40 * j);
          const di = pop[j].z[i] - mi;
          vv += w * di * di;
        }
        vv /= sumW;

        m[i] = mi;
        v[i] = vv;
      }

      const eta = (mode === "local") ? 0.55 : 0.45;

      for (let i = 0; i < N; i++) {
        mean[i] = (1 - eta) * mean[i] + eta * m[i];

        let ns = Math.sqrt(v[i]);
        ns = (1 - eta) * sig[i] + eta * ns;

        let floor = (mode === "local") ? 0.006 : 0.010;
        let cap = (mode === "local") ? 0.12 : (mode === "p5extra" ? 0.35 : 0.50);
        if (i === 3) cap = Math.min(cap, 0.15);
        if (i === 2) cap = Math.min(cap, 0.20);

        if (ns < floor) ns = floor;
        if (ns > cap) ns = cap;
        sig[i] = ns;
      }

      if (noImp > (mode === "local" ? 6 : 10) && gen > 2) {
        let cen = (mode === "p5extra") ? { x: makeX(P5) } : (bestFinished || bestOverall);
        if (cen && cen.x) {
          const zc = normX(cen.x);
          for (let i = 0; i < N; i++) {
            mean[i] = 0.60 * mean[i] + 0.40 * zc[i];
            const floor = (mode === "local") ? 0.03 : 0.08;
            if (sig[i] < floor) sig[i] = floor;
          }
        } else {
          for (let i = 0; i < N; i++) {
            mean[i] = 0.5 * mean[i] + 0.5 * Math.random();
            if (sig[i] < 0.15) sig[i] = 0.15;
          }
        }
        noImp = 0;
      }

      gen++;
      if (mode === "local" && gen > 14) break;
    }

    return bestOverall;
  }

  const p5Rec = evalX(makeX(P5));

  const seedList = [];
  let bestRunRec = null;
  let alternateSeedX = null;

  function addSeed(fn, tag) {
    let a = makeX(P5);
    if (fn) fn(a);
    a = makeX(a);
    seedList.push({ x: a, tag: tag || "p5" });
    if (tag === "run" && !alternateSeedX) alternateSeedX = a;
  }

  addSeed(function (a) {
    a[31] = 8; a[47] = 0.08;
  }, "p5");

  addSeed(function (a) {
    a[31] = 18; a[47] = 0.16; a[44] = 3;
  }, "p5");

  addSeed(function (a) {
    a[31] = 18; a[47] = 0.16; a[44] = -3;
  }, "p5");

  addSeed(function (a) {
    a[31] = 25; a[44] = -4; a[43] = 0.10;
  }, "p5");

  addSeed(function (a) {
    a[16] = 2.8; a[26] = -0.03; a[17] = 1.16; a[18] = 35.0;
    a[19] = 5.0; a[47] = 0.15; a[31] = 15;
  }, "p5");

  addSeed(function (a) {
    a[2] = 0.50; a[1] = 0.52; a[0] = 2.4; a[4] = 0.70;
    a[7] = 1.20; a[16] = 2.6; a[17] = 1.14; a[18] = 32.0;
    a[25] = 0.60; a[31] = 12; a[44] = -3; a[47] = 0.10;
    a[43] = 0.20; a[29] = 0.15;
  }, "run");

  addSeed(function (a) {
    a[2] = 1.00; a[1] = 0.45; a[0] = 2.2; a[4] = 0.55;
    a[7] = 1.50; a[16] = 2.4; a[17] = 1.12; a[18] = 30.0;
    a[25] = 0.50; a[31] = 22; a[44] = -5; a[47] = 0.12;
    a[29] = 0.20;
  }, "run");

  addSeed(function (a) {
    a[0] = 2.8; a[1] = 0.60; a[4] = 0.90; a[16] = 3.5;
    a[20] = -1.5; a[22] = 1.5; a[31] = 15; a[39] = 5; a[40] = 10;
  }, "run");

  addSeed(function (a) {
    a[2] = 0.50; a[1] = 0.45; a[0] = 2.7; a[4] = 0.75;
    a[7] = 1.05; a[16] = 2.7; a[25] = 0.55; a[31] = 22;
    a[47] = 0.18; a[44] = -2; a[41] = 0.10;
  }, "run");

  addSeed(function (a) {
    a[37] = 5; a[38] = 0.20; a[46] = 0.10; a[40] = 10;
  }, "p5");

  addSeed(function (a) {
    a[39] = 10; a[40] = 20; a[47] = 0.10;
  }, "p5");

  addSeed(function (a) {
    a[41] = 0.20; a[42] = 0.10; a[43] = 0.10;
  }, "p5");

  addSeed(function (a) {
    a[4] = 0.80; a[0] = 2.6; a[7] = 1.10; a[16] = 2.8;
    a[31] = 16; a[47] = 0.12;
  }, "run");

  addSeed(function (a) {
    a[13] = 18.0; a[14] = 9.0; a[15] = 2.0; a[16] = 3.0;
    a[0] = 2.2; a[31] = 12; a[47] = 0.10;
  }, "p5");

  addSeed(function (a) {
    a[20] = 0.0; a[21] = 0.0; a[22] = 0.0;
    a[4] = 0.65; a[0] = 2.0; a[16] = 2.2;
  }, "run");

  for (let r = 0; r < 16; r++) {
    let a = makeX(P5);
    for (let i = 0; i < 31; i++) {
      if (Math.random() < 0.10) {
        a[i] += gauss() * 0.10 * (UB[i] - LB[i]);
      }
    }
    for (let i = 31; i < N; i++) {
      if (Math.random() < 0.55) {
        a[i] = LB[i] + Math.random() * (UB[i] - LB[i]);
      }
    }
    seedList.push({ x: makeX(a), tag: "rand" });
  }

  for (let r = 0; r < 5; r++) {
    let a = makeX(DEF);
    for (let i = 0; i < N; i++) {
      if (Math.random() < 0.30) {
        a[i] = LB[i] + Math.random() * (UB[i] - LB[i]);
      }
    }
    seedList.push({ x: makeX(a), tag: "rand" });
  }

  for (let si = 0; si < seedList.length; si++) {
    if (left() <= 5 || timeUp()) break;
    const rec = evalX(seedList[si].x);
    if (seedList[si].tag === "run") {
      if (!bestRunRec || rec.fit > bestRunRec.fit) bestRunRec = rec;
    }
  }

  if (left() > 90 && !timeUp()) {
    runCEM(p5Rec, 220, 0.10, "p5extra");
  }

  if (left() > 80 && !timeUp()) {
    runCEM(bestOverall, 180, 0.15, "global");
  }

  if (left() > 70 && !timeUp()) {
    runCEM(bestFinished || bestOverall, 150, 0.09, "refine");
  }

  if (left() > 60 && !timeUp()) {
    if (bestRunRec) runCEM(bestRunRec, 130, 0.13, "run");
    else if (alternateSeedX) runCEM(alternateSeedX, 130, 0.13, "run");
  }

  if (left() > 50 && !timeUp()) {
    runCEM(bestOverall, 100, 0.05, "local");
  }

  function sameX(a, b) {
    if (!a || !b) return false;
    for (let i = 0; i < N; i++) {
      if (Math.abs((+a[i] || 0) - (+b[i] || 0)) > 1e-9) return false;
    }
    return true;
  }

  const sorted = records.slice().sort(function (a, b) { return b.fit - a.fit; });
  const candidates = [];

  for (let qi = 0; qi < sorted.length && candidates.length < 10; qi++) {
    const rec = sorted[qi];
    if (rec.dummy) continue;
    let dup = false;
    for (let ci = 0; ci < candidates.length; ci++) {
      if (sameX(rec.x, candidates[ci].x)) {
        dup = true;
        break;
      }
    }
    if (!dup) candidates.push(rec);
  }

  if (p5Rec) {
    let found = false;
    for (let ci = 0; ci < candidates.length; ci++) {
      if (sameX(candidates[ci].x, p5Rec.x)) {
        found = true;
        break;
      }
    }
    if (!found) candidates.push(p5Rec);
  }

  const robustResults = [];
  const maxCand = Math.min(candidates.length, 8);

  for (let ci = 0; ci < maxCand; ci++) {
    if (left() <= 6 || timeUp()) break;
    const cand = candidates[ci];
    let sum = cand.fit;
    let minScore = cand.fit;
    let cnt = 1;

    const offs = [-0.18, 0.18, -0.32, 0.32];

    for (let oi = 0; oi < offs.length; oi++) {
      if (left() <= 3 || timeUp()) break;
      const xx = makeX(cand.x);
      xx[3] += offs[oi];
      const r = evalX(xx);
      const sc = r.dummy ? -1e9 : r.fit;
      sum += sc;
      if (sc < minScore) minScore = sc;
      cnt++;
    }

    const avg = sum / cnt;
    const robust = avg + 0.12 * minScore;
    robustResults.push({ rec: cand, robust: robust, avg: avg, min: minScore });
  }

  let p5Robust = p5Rec ? p5Rec.fit : -1e9;
  for (let i = 0; i < robustResults.length; i++) {
    if (p5Rec && sameX(robustResults[i].rec.x, p5Rec.x)) {
      p5Robust = robustResults[i].robust;
      break;
    }
  }

  let bestRob = null;
  for (let i = 0; i < robustResults.length; i++) {
    if (!bestRob || robustResults[i].robust > bestRob.robust) {
