function policy(obs, params, mem) {
  const p = params || {};
  const clamp = (v, lo, hi) => (v < lo ? lo : v > hi ? hi : v);
  const num = (v) => (typeof v === 'number' && isFinite(v) ? v : 0);

  const t = num(obs[19]);
  const ang = num(obs[0]);
  const f = num(p.f) || 1.8;
  const ha = num(p.ha);
  const hb = num(p.hb);
  const ka = num(p.ka);
  const kb = num(p.kb);
  const off = num(p.off);
  const ksh = num(p.ksh);
  const bal = num(p.bal);
  const kp = num(p.kp) || 8;
  const kd = num(p.kd);

  const ph = 2 * Math.PI * f * t;

  // Hip targets: sinusoidal swing plus torso-lean compensation.
  let hipTA = hb + bal * ang + ha * Math.sin(ph);
  let hipTB = hb + bal * ang + ha * Math.sin(ph + off);

  // Knee targets: flex during part of the cycle.
  const sA = 0.5 - 0.5 * Math.cos(ph + ksh);
  const sB = 0.5 - 0.5 * Math.cos(ph + off + ksh);
  let kneeTA = kb + ka * sA;
  let kneeTB = kb + ka * sB;

  hipTA = clamp(hipTA, -0.9, 1.2);
  hipTB = clamp(hipTB, -0.9, 1.2);
  kneeTA = clamp(kneeTA, -1.7, -0.05);
  kneeTB = clamp(kneeTB, -1.7, -0.05);

  const pd = (target, angle, speed) => {
    const out = kp * (target - num(angle)) - kd * num(speed);
    return clamp(out, -1, 1);
  };

  const hipA = pd(hipTA, obs[5], obs[6]);
  const kneeA = pd(kneeTA, obs[7], obs[8]);
  const hipB = pd(hipTB, obs[10], obs[11]);
  const kneeB = pd(kneeTB, obs[12], obs[13]);

  return [hipA, kneeA, hipB, kneeB].map((v) => (isFinite(v) ? v : 0));
}

function learn(lab) {
  const S = [
    ['f', 0.8, 3.5],
    ['ha', 0.1, 0.9],
    ['hb', -0.4, 0.6],
    ['ka', 0.1, 1.4],
    ['kb', -1.5, -0.15],
    ['off', -3.14159, 3.14159],
    ['ksh', -3.14159, 3.14159],
    ['bal', -3, 3],
    ['kp', 3, 15],
    ['kd', 0.1, 1.0],
  ];
  const dec = (x) => {
    const o = {};
    S.forEach((s, i) => { o[s[0]] = s[1] + x[i] * (s[2] - s[1]); });
    return o;
