    const v = typeof o[s[0]] === 'number' ? o[s[0]] : (s[1] + s[2]) / 2;
    return c01((v - s[1]) / (s[2] - s[1]));
  });
  const gauss = () => {
    const u = Math.random() || 1e-12;
    const v = Math.random();
    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
  };
  const now = () => (typeof Date !== 'undefined' ? Date.now() : 0);
  const start = now();
  const budget = 140000;
  const timeLeft = () => (typeof Date !== 'undefined' ? now() - start < budget : true);

  let best = null;
  let bestF = -Infinity;
  const archive = [];
  const record = (x, f) => {
    archive.push({ x: x.slice(), f: f });
    archive.sort((a, b) => b.f - a.f);
    if (archive.length > 12) archive.length = 12;
  };

  const evalX = (x) => {
    const p = dec(x);
    let r;
    try {
      r = lab.trial(p);
    } catch (e) {
      return -1;
    }
    if (!r) return -1;
    let d = typeof r.distance === 'number' && isFinite(r.distance) ? r.distance : -1;
    if (r.outcome === 'invalid' || r.outcome === 'error') d = -1;
    let f = d;
    if (d >= 0 && r.outcome === 'finished') f = d + 0.5;
    if (f > bestF) { bestF = f; best = x.slice(); }
    record(x, f);
    return f;
  };

  // ---- separable CMA-ES state ----
  let lam = 14, mu = 7, w = [], mueff = 1, cs = 0.3, ds = 1, cc = 0.3, c1 = 0.01, cmu = 0.01, chiN = 1;
  const setup = (l) => {
    lam = l;
    mu = Math.floor(l / 2);
    w = [];
    let s = 0;
    for (let i = 0; i < mu; i++) { w[i] = Math.log(mu + 0.5) - Math.log(i + 1); s += w[i]; }
    let s2 = 0;
    for (let i = 0; i < mu; i++) { w[i] /= s; s2 += w[i] * w[i]; }
    mueff = 1 / s2;
    cs = (mueff + 2) / (N + mueff + 5);
    ds = 1 + 2 * Math.max(0, Math.sqrt((mueff - 1) / (N + 1)) - 1) + cs;
    cc = (4 + mueff / N) / (N + 4 + 2 * mueff / N);
    const sep = (N + 2) / 3;
    c1 = (2 / ((N + 1.3) * (N + 1.3) + mueff)) * sep;
    cmu = Math.min(1 - c1, (2 * (mueff - 2 + 1 / mueff) / ((N + 2) * (N + 2) + mueff)) * sep);
    chiN = Math.sqrt(N) * (1 - 1 / (4 * N) + 1 / (21 * N * N));
  };

  let m, sigma, d, ps, pc, gen;
  const resetState = (mean, sig) => {
    m = mean.slice();
    sigma = sig;
    d = new Array(N).fill(1);
    ps = new Array(N).fill(0);
    pc = new Array(N).fill(0);
    gen = 0;
  };

  let restarts = 0;

  try {
    // Attempt-7 returned params (5.96 m full run) and small variants.
    const P7 = { f: 1.6997666121084556, ha: 0.7805583161322991, hb: 0.2752462140379246, ka: 0.29644013946699754, kb: -1.2395080378820196, off: -2.1723017606237294, ksh: 2.873105623022256, bal: 4.713154849821533, bals: 0.4611166281273279, kv: 0.1905328626309989, kp: 11.072190549728784, kd: 0.38711139954986007, hur: 0.007952729292930234, kbal: -0.24678452420204022, kh: 0.028135657279949287 };
    const P4 = { f: 1.7065599795386182, ha: 0.6033184814157889, hb: 0.23489453353274137, ka: 0.13685234448898798, kb: -1.1811976483862496, off: -1.8882289575272369, ksh: 2.7582435384105466, bal: 3.8456701051937214, bals: 0.4192901221788605, kv: 0.2264278028484517, kp: 13.550552290224585, kd: 0.4398530239202233, hur: 0.13354484346403314, kbal: 0, kh: 0 };
    const seeds = [
      P7,
      Object.assign({}, P7, { hur: 0.1 }),
      Object.assign({}, P7, { kh: 0.8 }),
      P4,
    ];
    for (const so of seeds) {
      if (lab.trialsLeft() <= 0 || !timeLeft()) break;
      evalX(enc(so));
    }

    // Local sweep around the best seed.
    const baseX = best ? best.slice() : enc(P7);
    for (let k = 0; k < 30; k++) {
      if (lab.trialsLeft() <= 0 || !timeLeft()) break;
      const sg = k < 15 ? 0.05 : 0.12;
      const x = baseX.map((v) => c01(v + sg * gauss()));
      evalX(x);
    }

    setup(14);
    const meanX = best ? best.slice() : baseX;
    resetState(meanX, 0.06);

    while (lab.trialsLeft() > 0 && timeLeft()) {
      if (gen >= 60 || sigma < 1e-3 || !isFinite(sigma)) {
        restarts++;
        let mean, sig;
        if (archive.length && Math.random() < 0.5) {
          const e = archive[Math.floor(Math.random() * Math.min(4, archive.length))];
          mean = e.x.slice();
          sig = 0.05;
        } else {
          mean = S.map(() => Math.random());
          sig = 0.25;
        }
        setup(Math.min(48, 14 * Math.pow(2, Math.floor(restarts / 2))));
        resetState(mean, sig);
      }

      const n = Math.min(lam, lab.trialsLeft());
      if (n < 2) break;
      const pop = [];
      for (let k = 0; k < n; k++) {
        if (!timeLeft()) break;
        const x = [];
        for (let i = 0; i < N; i++) {
          const zi = gauss();
          x.push(c01(m[i] + sigma * zi * Math.sqrt(d[i])));
        }
        const fv = evalX(x);
        const y = x.map((xi, i) => (xi - m[i]) / sigma);
        pop.push({ x: x, f: fv, y: y });
      }
      if (pop.length < mu) break;

      pop.sort((a, b) => b.f - a.f);
      const mNew = new Array(N).fill(0);
      for (let k = 0; k < mu; k++) {
        for (let i = 0; i < N; i++) mNew[i] += w[k] * pop[k].x[i];
      }
      const yw = mNew.map((v, i) => (v - m[i]) / sigma);

      let normps2 = 0;
      for (let i = 0; i < N; i++) {
        ps[i] = (1 - cs) * ps[i] + Math.sqrt(cs * (2 - cs) * mueff) * yw[i] / Math.sqrt(d[i]);
        normps2 += ps[i] * ps[i];
      }
      const normps = Math.sqrt(normps2);
      gen++;
      const hs = (normps / Math.sqrt(1 - Math.pow(1 - cs, 2 * gen)) / chiN) < (1.4 + 2 / (N + 1)) ? 1 : 0;

      for (let i = 0; i < N; i++) {
        pc[i] = (1 - cc) * pc[i] + hs * Math.sqrt(cc * (2 - cc) * mueff) * yw[i];
        let rankMu = 0;
        for (let k = 0; k < mu; k++) rankMu += w[k] * pop[k].y[i] * pop[k].y[i];
        d[i] = (1 - c1 - cmu) * d[i]
          + c1 * (pc[i] * pc[i] + (1 - hs) * cc * (2 - cc) * d[i])
          + cmu * rankMu;
        if (!(d[i] > 1e-12)) d[i] = 1e-12;
        if (d[i] > 1e4) d[i] = 1e4;
      }

      sigma *= Math.exp((cs / ds) * (normps / chiN - 1));
      if (!(sigma > 1e-5)) sigma = 1e-5;
      if (sigma > 1) sigma = 1;
      m = mNew;
    }
  } catch (e) {
    // fall through and return the best found so far
  }

  if (best) return dec(best);
  if (archive.length) return dec(archive[0].x);
  return dec(enc({ f: 1.6997666121084556, ha: 0.7805583161322991, hb: 0.2752462140379246, ka: 0.29644013946699754, kb: -1.2395080378820196, off: -2.1723017606237294, ksh: 2.873105623022256, bal: 4.713154849821533, bals: 0.4611166281273279, kv: 0.1905328626309989, kp: 11.072190549728784, kd: 0.38711139954986007, hur: 0.007952729292930234, kbal: -0.24678452420204022, kh: 0.028135657279949287 }));
}
